UPDATE documents
SET status = #{status}
WHERE id = #{documentId}
  AND status = #{expectedStatus}

UPDATE documents
SET issued_on = #{issuedOn},
    expires_on = #{expiresOn}
WHERE id = #{documentId}
  AND owner_user_id = #{ownerUserId}
  AND document_type = 'HEALTH_CERTIFICATE'
  AND status = 'ACTIVE'

