UPDATE document_shares
SET status = 'REVOKED',
    revoked_at = #{revokedAt}
WHERE document_id = #{documentId}
  AND status = 'ACTIVE'

UPDATE document_shares
SET status = 'REVOKED',
    revoked_at = #{revokedAt}
WHERE document_id = #{documentId}
  AND status = 'ACTIVE'
  AND work_case_id IN (
      SELECT id FROM work_cases WHERE workplace_id = #{workplaceId}
